/* test_fb_cal.c — every calibration object of the feedback shadow
 * (app/fb_cal.c, GENERATED by tools/gen_fb_cal.py) re-encoded big-endian and
 * compared with the pristine stock image at its flash address, and every
 * stock pointer cell compared with the address the generator followed; exit
 * 77 (skipped) when the image is absent */
#include "app/fb_cal.h"
#include <stdio.h>

int main(void)
{
    FILE *f = fopen(TCU_STOCK_IMAGE, "rb");
    static unsigned char img[0x200000];
    unsigned bad = 0u, bytes = 0u;
    if (f == NULL) {
        printf("SKIP no stock image %s\n", TCU_STOCK_IMAGE);
        return 77;
    }
    if (fread(img, 1u, sizeof img, f) != sizeof img) {
        fclose(f);
        printf("FAIL short image\n");
        return 1;
    }
    fclose(f);
    for (unsigned i = 0u; i < FB_CAL_NCHECKS; i++) {
        const fb_cal_check_t *c = &FB_CAL_CHECKS[i];
        const unsigned char *p = &img[c->addr];
        if (c->kind == FB_K_PTR) {
            const unsigned long v = ((unsigned long)p[0] << 24) | ((unsigned long)p[1] << 16) |
                                    ((unsigned long)p[2] << 8) | p[3];
            bytes += 4u;
            if (v != c->count) {
                printf("FAIL pointer at 0x%06lX: 0x%06lX, generated 0x%06lX\n",
                       (unsigned long)c->addr, v, (unsigned long)c->count);
                bad++;
            }
            continue;
        }
        for (unsigned j = 0u; j < c->count; j++) {
            unsigned long v = 0u, w = 0u;
            unsigned sz = 1u;
            switch (c->kind) {
            case FB_K_U8:  w = ((const unsigned char *)c->data)[j]; sz = 1u; break;
            case FB_K_U16: w = ((const unsigned short *)c->data)[j]; sz = 2u; break;
            case FB_K_S16: w = (unsigned short)((const short *)c->data)[j]; sz = 2u; break;
            default:       w = ((const unsigned int *)c->data)[j]; sz = 4u; break;
            }
            for (unsigned b = 0u; b < sz; b++) {
                v = (v << 8) | p[sz * j + b];
            }
            bytes += sz;
            if (v != w) {
                printf("FAIL 0x%06lX[%u]: image 0x%lX, generated 0x%lX\n",
                       (unsigned long)c->addr, j, v, w);
                bad++;
            }
        }
    }
    printf("fb_cal: %u objects, %u bytes, %u differ from the image\n", FB_CAL_NCHECKS, bytes, bad);
    return bad == 0u ? 0 : 1;
}
